import "./compact-footer.css";

export interface CompactFooterLink {
  label: string;
  href: string;
}

export interface CompactFooterProps {
  brand: string;
  statement?: string;
  links: CompactFooterLink[];
  legalLinks?: CompactFooterLink[];
  copyright: string;
}

export function CompactFooter({
  brand,
  statement,
  links,
  legalLinks = [],
  copyright,
}: CompactFooterProps) {
  return (
    <footer className="tb-compact-footer">
      <div className="tb-compact-footer__brand">
        <strong>{brand}</strong>
        {statement ? <p>{statement}</p> : null}
      </div>
      <nav aria-label="Footer navigation">
        {links.map((link) => (
          <a href={link.href} key={`${link.label}-${link.href}`}>
            {link.label}
          </a>
        ))}
      </nav>
      <div className="tb-compact-footer__legal">
        <span>{copyright}</span>
        {legalLinks.map((link) => (
          <a href={link.href} key={`${link.label}-${link.href}`}>
            {link.label}
          </a>
        ))}
      </div>
    </footer>
  );
}

.tb-compact-footer {
  --tb-cf-ink: #e8ece6;
  --tb-cf-ground: #242927;
  --tb-cf-accent: #d8e359;
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(17rem, 100%), 1fr));
  gap: clamp(2rem, 5vw, 6rem);
  align-items: start;
  padding: clamp(2.25rem, 4%, 4rem) clamp(1.25rem, 5%, 5.5rem);
  color: var(--tb-cf-ink);
  background: var(--tb-cf-ground);
}

.tb-compact-footer,
.tb-compact-footer * {
  box-sizing: border-box;
}

.tb-compact-footer__brand strong {
  font-size: clamp(1.7rem, 4cqi, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.tb-compact-footer__brand p {
  max-width: 30rem;
  margin: 1rem 0 0;
  color: #bac2bd;
  line-height: 1.5;
}

.tb-compact-footer nav {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(7rem, 100%), 1fr));
  gap: 0.85rem 2rem;
}

.tb-compact-footer a {
  width: fit-content;
  color: inherit;
  text-decoration-thickness: 0.1em;
  text-underline-offset: 0.3em;
  overflow-wrap: anywhere;
  transition: color 140ms ease-out;
}

.tb-compact-footer a:hover {
  color: var(--tb-cf-accent);
}

.tb-compact-footer a:focus-visible {
  outline: 3px solid var(--tb-cf-accent);
  outline-offset: 4px;
}

.tb-compact-footer__legal {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  align-items: center;
  padding-top: 1.5rem;
  border-top: 1px solid rgb(232 236 230 / 0.24);
  color: #bac2bd;
  font-size: 0.82rem;
}

@media (forced-colors: active) {
  .tb-compact-footer {
    border-top: 1px solid CanvasText;
  }
}
